def main():
    global UPDATES
    gp = os.path.join(HERE, 'gap_updates.json')
    if os.path.exists(gp): UPDATES = UPDATES + json.load(open(gp))
    rows = json.load(open(os.path.join(HERE, 'rows.json')))
    hit = 0
    for u in UPDATES:
        m = u['match']; n = 0
        for r in rows:
            if r['shortName'] != m['shortName']: continue
            if 'varType' in m and r['varType'] != m['varType']: continue
            if 'context' in m and m['context'] not in r['context']: continue
            if 'section' in m and m['section'] not in r['section']: continue
            s = dict(u['set']); na = s.pop('notes_append', None)
            r.update(s); n += 1
            if na and na not in r['notes']: r['notes'] = (r['notes'] + ' ' + na).strip()
        if n == 0: print('WARNING: no row matches', m)
        hit += n
    json.dump(rows, open(os.path.join(HERE, 'rows.json'), 'w'))
    print('rows updated:', hit)
    runpy.run_path(os.path.join(HERE, 'gen_md.py'))
if __name__ == '__main__':
    main()
